namespace RevLink.Mobile.Views;
public class GaragePage:RevPage {
 bool explore;string search="";
 public GaragePage():base("Garagem"){}
 protected override async Task Load(){Reset("GARAGEM","YOUR CAR. YOUR CULTURE.");var tabs=new Grid{ColumnDefinitions={new ColumnDefinition{Width=GridLength.Star},new ColumnDefinition{Width=GridLength.Star}},ColumnSpacing=8};tabs.Add(Ui.Button("Minha garagem",async()=>{explore=false;await Reload();},explore?Ui.Surface:Ui.Accent,explore?Ui.White:Ui.Get("Black")),0);tabs.Add(Ui.Button("Explorar",async()=>{explore=true;await Reload();},explore?Ui.Accent:Ui.Surface,explore?Ui.Get("Black"):Ui.White),1);Add(tabs);
 if(explore){var input=Ui.Entry("Marca, modelo ou apelido",search);Add(input,Ui.Button("Buscar",async()=>{search=Ui.Value(input);await Reload();}));}else Add(Ui.Button("+ ADICIONAR VEÍCULO",()=>Open(new CarForm())));
 var cars=await Api.Get<List<CarDto>>(explore?"/api/cars?q="+Uri.EscapeDataString(search):"/api/cars/mine");if(cars.Count==0){Add(Ui.Text("Nenhum veículo encontrado.",15,Ui.Muted));return;}
 var grid=new Grid{ColumnDefinitions={new ColumnDefinition{Width=GridLength.Star},new ColumnDefinition{Width=GridLength.Star}},ColumnSpacing=10,RowSpacing=10};for(int i=0;i<cars.Count;i++){var c=cars[i];if(i%2==0)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var tile=Ui.Card(Ui.Picture(c.PhotoUrl,125),Ui.Text(c.Nickname,17,Ui.White,true),Ui.Text($"{c.Brand} {c.Model}",13),Ui.Text(c.Style.ToUpperInvariant(),12,Ui.Accent,true),Ui.Text(c.OwnerTag,12,Ui.Muted));var tap=new TapGestureRecognizer();tap.Tapped+=async (_,_)=>await Open(new CarDetails(c.Id));tile.GestureRecognizers.Add(tap);grid.Add(tile,i%2,i/2);}Add(grid);}
}
public class CarDetails(int id):RevPage("Veículo") {
 protected override async Task Load(){var c=await Api.Get<CarDto>($"/api/cars/{id}");Reset(c.Nickname,$"GARAGEM DE {c.OwnerTag.ToUpperInvariant()}");Add(Ui.Picture(c.PhotoUrl,280),Ui.Card(Ui.Text($"{c.Brand} {c.Model} · {c.Year}",23,Ui.White,true),Ui.Text(c.Engine),Ui.Text(c.Style.ToUpperInvariant(),15,Ui.Accent,true)));if(c.UserId==Api.Me?.Id)Add(Ui.Button("Editar veículo",()=>Open(new CarForm(c))),Ui.Button("Excluir veículo",async()=>{if(await Confirm("Excluir este veículo? As publicações serão mantidas.")){await Api.Write(HttpMethod.Delete,$"/api/cars/{c.Id}");await Navigation.PopAsync();}},Ui.Surface,Ui.Danger));}
}
public class CarForm:FormPage {
 public CarForm(CarDto? car=null):base(car==null?"Novo veículo":"Editar veículo") {var photo=PhotoInput(car?.PhotoUrl);var nickname=Ui.Entry("Apelido",car?.Nickname);var brand=Ui.Entry("Marca",car?.Brand);var model=Ui.Entry("Modelo",car?.Model);var year=Ui.Entry("Ano",car?.Year.ToString(),Keyboard.Numeric);var engine=Ui.Entry("Motorização",car?.Engine);var styles=new[]{"Stock","Street","JDM","Stance","Track","Classic","Off-road","Custom"};var style=new Picker{Title="Estilo",ItemsSource=styles,SelectedIndex=car==null?0:Array.IndexOf(styles,car.Style)};
 Add(photo.preview,photo.button,Ui.Text("IDENTIFICAÇÃO",13,Ui.Accent,true),nickname,brand,model,year,engine,style,Ui.Button("SALVAR VEÍCULO",async()=>{if(!int.TryParse(Ui.Value(year),out int y)||style.SelectedItem==null)throw new Exception("Informe ano e estilo.");await Api.Write(car==null?HttpMethod.Post:HttpMethod.Put,car==null?"/api/cars":$"/api/cars/{car.Id}",new{nickname=Ui.Value(nickname),brand=Ui.Value(brand),model=Ui.Value(model),year=y,engine=Ui.Value(engine),style=(string)style.SelectedItem,photo=photo.data()});await Finish();}));}
}
